function edit(kind,id){const e=selected();if(kind!=='event'&&!e)return;const item=kind==='event'?(id?state.events.find(x=>x.id===id):C.blankEvent()):(id?e[kind].find(x=>x.id===id):{id:C.uid()});editor={kind,item,original:!!id};const title=kind==='event'?'REA event':schemas[kind].title;$('#editor-title').textContent=`${id?'Edit':'Add'} ${title.toLowerCase()}`;$('#editor-hint').textContent=kind==='notices'?'Confirm clause applicability and the calculated deadline. Business days exclude weekends only; review holidays and contract terms manually.':kind==='costs'?'Negative amounts and credits are preserved. The worksheet does not decide cost allowability.':'';$('#editor-fields').innerHTML=editorFields(kind,item,!!id);$('#editor-error').hidden=true;$('#editor').showModal();$('#editor-fields input:not([readonly]),#editor-fields select,#editor-fields textarea').focus();}
