function closeDialog(dialog){dialog.close();editor=null;$('#main').focus();}
function saveEditor(ev){
  ev.preventDefault();
  const {kind,item,original}=editor,previous=kind==='assignments'&&original?structuredClone(item):null;
  const fields=kind==='event'?eventFields:kind==='basis'?basisFields:schemas[kind].fields;
  const draft=structuredClone(item);
  for(const f of fields){if(f.type==='calculated')continue;const el=$(`#f-${f.key}`);draft[f.key]=f.type==='checkbox'?el.checked:el.value.trim();}
  const fail=message=>{$('#editor-error').textContent=message;$('#editor-error').hidden=false;return false;};
  if(kind==='event'&&(!draft.identifier||!draft.title||!draft.contract))return fail('Event identifier, title, and contract number are required.');if(kind==='event'&&state.events.some(x=>x.id!==item.id&&x.identifier.toLowerCase()===draft.identifier.toLowerCase()&&x.contract.toLowerCase()===draft.contract.toLowerCase()))return fail('This event identifier is already used for the contract.');
  if(kind==='evidence'){
    if(!draft.identifier)return fail('Enter a unique evidence identifier.');
    if(selected().evidence.some(x=>x.id!==item.id&&x.identifier.toLowerCase()===draft.identifier.toLowerCase()))return fail('This evidence identifier is already used in this event.');
  }
  if(kind==='notices'){
    if(draft.triggerDate&&!C.validDate(draft.triggerDate))return fail('Enter a valid trigger date.');
    if(draft.period!==''&&(!Number.isInteger(Number(draft.period))||Number(draft.period)<0||Number(draft.period)>3650))return fail('Enter a whole-number period from 0 to 3650 days.');
  }
  if(kind==='rates'&&(!draft.name||!draft.period))return fail('Enter the burden name and effective period.');
  if(['costs','rates'].includes(kind)&&['quantity','rate'].some(key=>draft[key]!==undefined&&draft[key]!==''&&!Number.isFinite(Number(draft[key]))))return fail('Enter finite numeric amounts.');
  Object.assign(item,draft);
  if(kind==='event'){if(!original)state.events.push(item);state.selectedId=item.id;}
  else if(kind!=='basis'){
    if(!original)selected()[kind].push(item);
    if(previous&&JSON.stringify(previous)!==JSON.stringify(item)){selected().assignmentRevisions ||= [];selected().assignmentRevisions.push({id:C.uid(),assignmentId:item.id,recordedAt:new Date().toISOString(),previous});}
  }
  closeDialog($('#editor'));save();render();
}
